import{_ as d,o as t,c as e,a2 as c}from"./chunks/framework.CuUVYbLV.js";const g=JSON.parse('{"title":"迁移对照","description":"v0.x → v1.9.0 的破坏性变更清单与升级指南 — 声明式协作与终止子系统移除、dispatch 到 graph 的路径迁移、逐条旧写法与新写法对照","frontmatter":{"title":"迁移对照","description":"v0.x → v1.9.0 的破坏性变更清单与升级指南 — 声明式协作与终止子系统移除、dispatch 到 graph 的路径迁移、逐条旧写法与新写法对照"},"headers":[],"relativePath":"06-Appendix/migration.md","filePath":"06-Appendix/migration.md"}'),a={name:"06-Appendix/migration.md"};function r(i,o,l,n,s,h){return t(),e("div",null,[...o[0]||(o[0]=[c('<h1 id="迁移对照-migration" tabindex="-1">迁移对照（Migration） <a class="header-anchor" href="#迁移对照-migration" aria-label="Permalink to &quot;迁移对照（Migration）&quot;">​</a></h1><p>本页回答一个问题：<strong>把旧版本的 rolebox 升级到 v1.9.0，我需要改什么。</strong> 内容分四部分：迁移的前提（没有自动迁移命令）、逐版本破坏性变更清单、<code>dispatch</code> → <code>graph</code> 的路径迁移，以及按起点版本排列的升级顺序。</p><blockquote><p>相关：<a href="/rolebox-docs/02-Guide/collaboration-graph.html">协作图（已移除）</a>｜<a href="/rolebox-docs/04-Advanced/termination-conditions.html">终止条件（已移除）</a>｜<a href="/rolebox-docs/04-Advanced/compatibility.html">兼容性</a>｜<a href="/rolebox-docs/03-Reference/cli.html">CLI 参考</a></p></blockquote><h2 id="迁移是配置改写-不是执行一条命令" tabindex="-1">迁移是配置改写，不是执行一条命令 <a class="header-anchor" href="#迁移是配置改写-不是执行一条命令" aria-label="Permalink to &quot;迁移是配置改写，不是执行一条命令&quot;">​</a></h2><p>rolebox 没有自动迁移入口，也没有把声明式配置转成命令式图文档的转换器。v1.9.0 的 14 个 CLI 子命令是 <code>init</code>、<code>install</code>、<code>uninstall</code>、<code>sync</code>、<code>list</code>、<code>search</code>、<code>update</code>、<code>registry</code>、<code>status</code>、<code>info</code>、<code>config</code>、<code>monitor</code>、<code>memory</code>、<code>checkpoint</code>——里面没有任何一个负责迁移。</p><p>升级动作全部落在你自己的文件上，共三类：</p><ol><li><strong>删</strong> —— 从 <code>role.yaml</code> 中删除已移除的块（<code>collaboration:</code> 及其 <code>termination</code> 字段）。</li><li><strong>改</strong> —— 把多代理工作流从声明式改写为命令式 <code>graph_*</code> 调用（见「旧写法 → 新写法」）。</li><li><strong>对</strong> —— 按破坏性变更清单处理运行时与依赖变化（状态目录、SQLite 驱动、目标 harness）。</li></ol><blockquote><p><code>migrate</code> 命令确实存在过：v1.0.0 引入，v1.8.0 随声明式子系统一并<strong>已移除</strong>。v1.9.0 不存在该子命令，也没有替代品。</p></blockquote><h2 id="破坏性变更清单-v0-x-→-v1-9-0" tabindex="-1">破坏性变更清单（v0.x → v1.9.0） <a class="header-anchor" href="#破坏性变更清单-v0-x-→-v1-9-0" aria-label="Permalink to &quot;破坏性变更清单（v0.x → v1.9.0）&quot;">​</a></h2><table tabindex="0"><thead><tr><th>版本</th><th>变更</th><th>所需操作</th></tr></thead><tbody><tr><td>v1.8.0</td><td>声明式协作与终止子系统移除</td><td>删除 <code>collaboration:</code> 块；多代理工作流改写为 <code>graph_*</code></td></tr><tr><td>v1.0.0</td><td>v1 图子系统退役 + 工具面整合</td><td>编排统一走 <code>graph_*</code>；面向模型的 <code>dispatch_*</code> / <code>loop_*</code> 退役，保留薄 <code>task_*</code> 兼容层；<code>function_state</code> 工具移除</td></tr><tr><td>v0.24.0</td><td><code>task_*</code> → <code>dispatch_*</code> 工具重命名</td><td>旧名保留为弃用别名；该重命名随后被 v1.0.0 的工具面整合覆盖</td></tr><tr><td>v0.23.0</td><td>TUI 键盘交互移除</td><td>改用鼠标点击；快捷键迁移到 <code>Ctrl+</code> 前缀</td></tr><tr><td>v0.20.0</td><td>持久记忆系统、微内核架构、TUI 引入</td><td>当时需要 Bun ≥ 1.1.0；v1.0.0 起记忆子系统改为双运行时 SQLite 驱动，不再强制 Bun</td></tr><tr><td>v0.17.0</td><td>会话工具套件、LSP 集成、Hashline 编辑引入</td><td>更新 peer 依赖（<code>@opencode-ai/plugin</code> 为 <code>^1.3.0</code>）</td></tr><tr><td>v0.15.0</td><td><code>|loop|</code> 语义重写</td><td>每轮循环（含第一轮）都在子工作线程中运行，主线程变为纯编排角色</td></tr><tr><td>v0.12.0</td><td>状态存储迁移</td><td>状态目录从 <code>XDG_DATA_HOME</code> 变更为项目本地 <code>.rolebox/</code>；旧数据需手动迁移</td></tr><tr><td>v0.10.0</td><td>Dispatch 调度系统重写</td><td>全局轮询模式被 <code>TaskWatchdogManager</code> 取代；建议清空旧的 <code>.rolebox/state/</code></td></tr></tbody></table><p>更细的版本历史见 <a href="https://github.com/EricMoin/rolebox/blob/main/CHANGELOG.md" target="_blank" rel="noreferrer">rolebox CHANGELOG</a>。</p><h2 id="v1-8-0-声明式协作与终止子系统移除" tabindex="-1">v1.8.0：声明式协作与终止子系统移除 <a class="header-anchor" href="#v1-8-0-声明式协作与终止子系统移除" aria-label="Permalink to &quot;v1.8.0：声明式协作与终止子系统移除&quot;">​</a></h2><p>这是离 v1.9.0 最近的一次语义断裂。<code>role.yaml</code> 的 <code>collaboration:</code> 块（<code>topology</code> / <code>flow</code> / <code>agents</code> / <code>max_iterations</code> / <code>termination</code>）整体从 schema 中删除，同时删除的还有终止声明类型词汇表、<code>termination_conditions</code> 扩展点、<code>graph_add_loop</code> 的 <code>termination</code> 参数，以及移植过来的 <code>collaboration-*</code> 图模块与 v1 残留（含 v1 graph-session 运行时状态读取器、其 compaction 与 <code>monitor</code> 界面、四个示例协作角色）。</p><p>逐类删除清单见<a href="/rolebox-docs/02-Guide/collaboration-graph.html">协作图（已移除）</a>。<strong>没有任何自动转换器</strong>：删除 <code>collaboration:</code> 块后按图文档手写；终止语义的现状见<a href="/rolebox-docs/04-Advanced/termination-conditions.html">终止条件（已移除）</a>。</p><h2 id="v1-0-0-dispatch-→-graph-的路径迁移" tabindex="-1">v1.0.0：dispatch → graph 的路径迁移 <a class="header-anchor" href="#v1-0-0-dispatch-→-graph-的路径迁移" aria-label="Permalink to &quot;v1.0.0：dispatch → graph 的路径迁移&quot;">​</a></h2><p>v1.0.0 把多代理编排的入口从「面向模型的调度工具」收缩到命令式图引擎：</p><ul><li><strong>编排统一走 <code>graph_*</code></strong>：<code>graph_create</code> → <code>graph_add_node</code> / <code>graph_add_edge</code> → <code>graph_run</code> → <code>graph_status</code>。图节点是角色无关的 <code>{agent, prompt}</code> 元组。</li><li><strong>v1 图子系统退役</strong>：v1 执行子系统被移除，其语义先被移植进 <code>collaboration-*</code> 模块并以 <code>collaboration-{hash}.json</code> 路径持久化，这套模块又在 v1.8.0 被删除。</li><li><strong><code>dispatch_*</code> / <code>loop_*</code> 退役</strong>：面向模型的裸调度工具与 checkpoint / budget / concurrency / query 套件一并退役，只保留一层薄的 <code>task_*</code> 兼容工具。</li><li><strong><code>function_state</code> 工具移除</strong>：函数状态不再由独立工具查询，状态观察走 <code>graph_status</code>。</li></ul><p>如果你从 v1.0 之前升级，这一步比 v1.8.0 影响更大——它是「编排入口换了」，而不只是「某个配置块没了」。</p><h2 id="旧写法-→-新写法" tabindex="-1">旧写法 → 新写法 <a class="header-anchor" href="#旧写法-→-新写法" aria-label="Permalink to &quot;旧写法 → 新写法&quot;">​</a></h2><table tabindex="0"><thead><tr><th>旧写法（已移除或已退役）</th><th>新写法</th></tr></thead><tbody><tr><td><code>collaboration:</code> 块（<code>topology</code> / <code>flow</code> / <code>agents</code>）</td><td>删除该块；用 <code>graph_create</code> + <code>graph_add_node</code> + <code>graph_add_edge</code> 搭出同一拓扑</td></tr><tr><td><code>collaboration.max_iterations</code></td><td><code>graph_add_loop</code> 的 <code>max_traversals</code>（硬上限，整数 ≥ 1）</td></tr><tr><td><code>collaboration.termination</code> 的 <code>any_of</code> / <code>all_of</code></td><td><code>max_traversals</code> 硬上限 + <code>graph_status</code> 观测 + <code>graph_cancel</code> 终止</td></tr><tr><td><code>graph_add_loop</code> 的 <code>termination</code> 参数</td><td>只传 <code>nodes</code> + <code>max_traversals</code>；会话隔离模式用 <code>mode</code></td></tr><tr><td>面向模型的 <code>dispatch_*</code> / <code>loop_*</code> 工具</td><td><code>graph_*</code> 编排；需要调度自省时用薄的 <code>task_*</code> 兼容工具</td></tr><tr><td>v1 图文档与 <code>collaboration-{hash}.json</code> 状态</td><td>命令式 <code>graph_*</code> 工具；引擎状态由引擎自己持久化</td></tr><tr><td><code>function_state</code> 工具</td><td>已移除；用 <code>graph_status</code> 观察节点状态</td></tr><tr><td><code>rolebox migrate</code></td><td>该子命令不存在；手工改写配置</td></tr><tr><td>状态目录 <code>XDG_DATA_HOME</code></td><td>项目本地 <code>.rolebox/</code>（旧数据需手动复制）</td></tr><tr><td>TUI 键盘快捷键</td><td>鼠标交互，快捷键加 <code>Ctrl+</code> 前缀</td></tr></tbody></table><h2 id="升级指南" tabindex="-1">升级指南 <a class="header-anchor" href="#升级指南" aria-label="Permalink to &quot;升级指南&quot;">​</a></h2><p>按「语义断裂点」升级，而不是按版本号逐个平推：</p><ul><li><strong>从 v0.5.x 及更早</strong>：v0.6.0（References 与协作图系统）→ v0.10.0（Dispatch 重写）→ v0.12.0（状态迁移）→ v0.15.0（<code>|loop|</code> 重写）→ v0.17.0（会话工具 / LSP / Hashline）→ v0.20.0（记忆系统、微内核、TUI）→ v1.0.0（图优先）→ v1.8.0（声明式协作移除）→ v1.9.0（跨 harness 对齐）。</li><li><strong>从 v0.17.x 附近</strong>：v0.20.0（记忆与 TUI）→ v0.23.0（TUI 鼠标化）→ v0.24.0（<code>task_*</code> → <code>dispatch_*</code> 重命名）→ v1.0.0（图优先，工具面再整合）→ v1.8.0（移除）→ v1.9.0。</li><li><strong>从 v1.0 – v1.7</strong>：只需处理 v1.8.0 的移除语义与 v1.9.0 的 harness 对齐；<code>pi</code> / <code>dsh</code> 作为同步目标自 v1.3.0 起可用。</li><li><strong>从 v1.8.x</strong>：无需迁移配置；v1.9.0 是 dsh web UI 与图门禁的修复版本。</li></ul><p>每一步之后用 <code>rolebox sync &lt;opencode|pi|dsh&gt;</code> 重新部署角色，变更才在 harness 中生效。</p><h2 id="弃用时间线" tabindex="-1">弃用时间线 <a class="header-anchor" href="#弃用时间线" aria-label="Permalink to &quot;弃用时间线&quot;">​</a></h2><table tabindex="0"><thead><tr><th>版本</th><th>弃用项</th><th>替代方案</th><th>状态</th></tr></thead><tbody><tr><td>v1.8.0</td><td>声明式协作与终止条件词汇</td><td>命令式 <code>graph_*</code> 图引擎</td><td>已移除</td></tr><tr><td>v1.0.0</td><td>v1 图子系统与面向模型的 <code>dispatch_*</code> / <code>loop_*</code> 工具</td><td>v2 图引擎 + <code>task_*</code> 兼容层</td><td>已替换</td></tr><tr><td>v0.23.0</td><td>TUI 键盘交互模式</td><td>鼠标交互（<code>Ctrl+</code> 前缀快捷键）</td><td>已移除</td></tr><tr><td>v0.22.0</td><td><code>OpencodeClient</code> 会话接口</td><td><code>ISessionClient</code> 平台抽象层</td><td>已替换</td></tr><tr><td>v0.15.0</td><td><code>LoopManager</code> 顺序状态机</td><td><code>LoopCoordinator</code> 推链调度</td><td>已替换</td></tr><tr><td>v0.12.0</td><td><code>XDG_DATA_HOME</code> 状态存储</td><td>项目本地 <code>.rolebox/</code> 目录</td><td>已迁移</td></tr><tr><td>v0.10.0</td><td>全局轮询 Dispatch 模式</td><td><code>TaskWatchdogManager</code> 事件驱动</td><td>已替换</td></tr></tbody></table><h2 id="常见错误" tabindex="-1">常见错误 <a class="header-anchor" href="#常见错误" aria-label="Permalink to &quot;常见错误&quot;">​</a></h2><ul><li><strong>在 <code>role.yaml</code> 里保留 <code>collaboration:</code> 块</strong>。v1.9.0 不再解析它，也不会给出迁移提示——它只是一个未知键。</li><li><strong>升级后配置看起来「没生效」</strong>。改了 <code>role.yaml</code> 但没跑 <code>rolebox sync &lt;target&gt;</code>；角色目录里的副本仍是旧的。</li><li><strong>指望自动转换</strong>。不存在把声明式工作流转成 <code>graph_*</code> 调用的工具，也不存在 <code>rolebox migrate</code>。</li><li><strong>沿用旧的记忆数据库路径</strong>。状态目录自 v0.12.0 起是项目本地 <code>.rolebox/</code>；记忆数据库由工作区路径推导，不会自动从 <code>XDG_DATA_HOME</code> 搬过来。</li></ul><h2 id="下一步" tabindex="-1">下一步 <a class="header-anchor" href="#下一步" aria-label="Permalink to &quot;下一步&quot;">​</a></h2><ul><li><a href="/rolebox-docs/02-Guide/collaboration-graph.html">协作图（已移除）</a> — 声明式协作图的移除范围与字段级迁移要点</li><li><a href="/rolebox-docs/04-Advanced/termination-conditions.html">终止条件（已移除）</a> — 终止子系统的移除范围与仍生效的终止语义</li><li><a href="/rolebox-docs/02-Guide/graph-workflows.html">图工作流</a> — 用 <code>graph_*</code> 工具编写现行多代理工作流</li><li><a href="/rolebox-docs/04-Advanced/compatibility.html">兼容性</a> — 各 harness 的能力矩阵与运行时要求</li></ul>',30)])])}const v=d(a,[["render",r]]);export{g as __pageData,v as default};
